    "continuity_memory_focus": "good",
    "medical_safety_risk_recognition": "excellent",
    "patient_family_realworld_adaptation": "excellent"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00079",
          "explanation": "Doctor provided a realistic fallback if the original team was hard to reach.",
          "quote": "如果交通或时间实在困难"
        },
        {
          "event_id": "lite_evt_00095",
          "explanation": "Caregiver confirmed the adapted pathway was executed at the original hospital.",
          "quote": "已经按您说的来了原来做手术的医院"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by uncertainty about whether to wait or go to emergency care and unclear follow-up ownership. The doctor gave a stepwise route—original surgical hospital/ED or nearby ED fallback, materials to bring, triage phrasing, and waiting-period instructions—and the caregiver executed it.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00079",
          "explanation": "Doctor reframed the case as compounded wound and glucose risk after new data.",
          "quote": "风险叠加"
        },
        {
          "event_id": "lite_evt_00182",
          "explanation": "Doctor later reprioritized after hospital data, distinguishing non-DKA from ongoing infection/glucose/wound risks.",
          "quote": "不像严重酮症酸中毒"
        }
      ],
      "completion": "complete",
      "explanation": "HO2 was triggered when the caregiver supplied drainage/odor, temperature, limited intake, and glucose 18.6. The doctor changed the pathway to same-day hospital evaluation, then adapted again once onsite testing suggested no severe ketoacidosis while keeping infection, wound depth, glucose control, and medication safety active.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00182",
          "explanation": "Doctor named unresolved issues and avoided claiming surgery or wound resolution was decided.",
          "quote": "要看培养结果、伤口到底多深、血糖能不能稳住"
        }
      ],
      "completion": "partial",
      "explanation": "HO3 was triggered near the end as the caregiver asked whether to stay and how serious it was. The doctor bounded the decision to stay for observation/admission and left cultures, wound depth, and surgery to the hospital team, but did not fully list all residual uncertainties with owners and timing in a distinct closure summary.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": false,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00148",
          "explanation": "Doctor did use the workspace, but the visible result only shows availability of records, not integration of two specific record facts into the plan.",
          "quote": "可见既往/CareLoop 中心医院记录 5 条"
        }
      ],
      "completion": "partial",
      "explanation": "HO4 was triggered by unclear records, bone cement detachment, and medication uncertainty. Although the doctor queried the workspace and avoided fabricating missing results, the patient-facing reasoning did not clearly integrate at least two retrieved record-specific facts such as chronic osteomyelitis/soft tissue defect descriptors or current absence of lab/culture data as record-grounded findings.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": false,
      "triggered": true
    }
  ],
